def transform(grid):
    out = [row[:] for row in grid]
    # Connect the shared columns of the matching-color top and bottom markers,
    # stopping at the full-width separator; use the next color.
    top = grid[0]
    bottom = grid[-1]
    marker = next((v for v in top if v != 0), 0)
    separator = next((r for r, row in enumerate(grid) if r > 0 and all(v == 2 for v in row)), len(grid)-1)
    for c in range(len(top)):
        if top[c] == marker and bottom[c] == marker:
            for r in range(1, separator):
                out[r][c] = (marker + 1) % 10
    return out

